// SECURITY: pre-LLM scan for patient identifiers and prompt-injection phrases (runs BEFORE any model call)
const d = $json;
const ascii = s => String(s || '')
  .replace(/[٠-٩]/g, c => String(c.charCodeAt(0) - 0x0660))
  .replace(/[۰-۹]/g, c => String(c.charCodeAt(0) - 0x06F0));
const phi = [
  { k: 'national_id', r: /\b\d{14}\b/g },
  { k: 'phone', r: /(?<!\d)(?:\+?20|0)1[0125]\d{8}(?!\d)/g },
  { k: 'mrn', r: /\bMRN[:\s-]*\d+/gi },
  { k: 'email', r: /[\w.+-]+@[\w-]+\.[\w.]+/g },
  { k: 'name_label', r: /\b(patient|pt)\s+name\s*[:=]\s*\S+/gi }
];
const inj = [/ignore (all |any )?(previous|prior) instructions/i, /system prompt/i, /you are now/i,
  /disregard (the )?(above|rules)/i, /reveal .*(prompt|instructions)/i, /developer (message|mode)/i];
const fields = ['description', 'harm_description', 'person_affected'];
const types = new Set(); let injHit = false; const red = {};
for (const f of fields) {
  let t = ascii(d[f]);
  for (const p of phi) { if (p.r.test(t)) { types.add(p.k); } p.r.lastIndex = 0; t = t.replace(p.r, '[REDACTED-' + p.k + ']'); }
  if (inj.some(r => r.test(t))) injHit = true;
  red[f] = t;
}
const phiHit = types.size > 0;
return { json: { ...d, phi_status: (phiHit || injHit) ? 'quarantine' : 'clean',
  phi_flags: { phi: phiHit, injection: injHit, types: [...types] },
  description_redacted: red.description } };

const d = $json;
const req = ['incident_id', 'timestamp', 'incident_type', 'department', 'description_sanitized', 'harm_occurred', 'phi_status'];
const errors = req.filter(k => !d[k] || String(d[k]).trim() === '').map(k => 'missing: ' + k);
if (/^yes/i.test(d.harm_occurred || '') && !String(d.harm_description || '').trim()) errors.push('missing: harm_description (harm was reported)');
const t = String(d.incident_type || '').toLowerCase();
const rules = {
  clinical: /(medic|clinical|fall|infection|surgical|procedur|diagnos)/,
  security: /(security|access|data|cyber|violence)/,
  facility: /(facility|equipment|fire|environment|maintenance|power)/,
  safety: /(safety|near miss|other)/
};
const matches = Object.keys(rules).filter(k => rules[k].test(t));
const route = matches.length === 1 ? matches[0] : 'manual_triage';
const triage_reason = matches.length === 1 ? 'keyword match: ' + matches[0]
  : (matches.length === 0 ? 'no domain keyword matched' : 'conflicting domains: ' + matches.join(', '));
const h = String(d.harm_occurred || '').toLowerCase();
const sentinel_suspected = /(severe|death|died|permanent)/.test(h);
const escalation_flag = sentinel_suspected || /unknown/.test(h) || route === 'manual_triage';
const now = Date.now();
// GAHAR Hospital Standards 2025 / GAHAR accreditation-procedure update (12 Apr 2026): notify GAHAR within 48 h, RCA within 45 days.
const gahar_notify_by = sentinel_suspected ? new Date(now + 48 * 3600e3).toISOString() : '';
const rca_due_by = sentinel_suspected ? new Date(now + 45 * 86400e3).toISOString().slice(0, 10) : '';
return { json: { ...d, run_id: String($execution.id || 'manual'), schema_version: '2.0',
  validated: errors.length === 0, route, triage_reason, sentinel_suspected, escalation_flag,
  gahar_notify_by, rca_due_by, validation_errors: errors, sanitized_fields: req } };

const raw = $json.specialist_report || '';
let p;
try { p = JSON.parse(String(raw).replace(/```json|```/g, '').trim()); }
catch (e) { p = { summary: String(raw), confirmed_facts: [], hypotheses: [], missing_evidence: ['Specialist output was not valid JSON'], root_causes: [], recommendations: [], gahar_citations: [], risk_tier: 'High' }; }
const cites = Array.isArray(p.gahar_citations) ? p.gahar_citations : [];
const tier = ['Low', 'Medium', 'High', 'Critical'].includes(p.risk_tier) ? p.risk_tier : 'High';
return { json: { ...$json, parsed: p, gahar_citations: cites, risk_tier: tier } };

const parseJ = s => { try { return JSON.parse(String(s || '').replace(/```json|```/g, '').trim()); } catch (e) { return null; } };
const steps = Array.isArray($json.intermediateSteps) ? $json.intermediateSteps : [];
const observed = steps.map(s => typeof s.observation === 'string' ? s.observation : JSON.stringify(s.observation || '')).join('\n').toUpperCase();
const grounded = c => { const k = String(c || '').trim().toUpperCase(); return k.length >= 3 && observed.includes(k); };
const S = v => String(v == null ? '' : v).trim();
const base = $('JS Parser').item.json;
const v = parseJ($json.output);
const STATUS = ['Met', 'Partially met', 'Not met', 'Insufficient evidence'];
const norm = s => STATUS.find(x => x.toLowerCase() === S(s).toLowerCase()) || 'Insufficient evidence';
const raw = v && Array.isArray(v.checks) ? v.checks : [];
const checks = raw.map((c, i) => { const g = grounded(c.standard_code);
  return { ref: 'V' + (i + 1), standard_code: S(c.standard_code), standard_title: S(c.standard_title), requirement_summary: S(c.requirement_summary),
    status: g ? norm(c.status) : 'Unverified reference', evidence_from_incident: S(c.evidence_from_incident), grounded: g }; });
const count = s => checks.filter(c => c.status === s).length;
const align = v && ['Aligned', 'Partially aligned', 'Not aligned', 'Cannot determine'].includes(v.overall_alignment) ? v.overall_alignment : 'Cannot determine';
const validation = { ok: v !== null, retrieval_calls: steps.length, checks, unsupported_claims: v && Array.isArray(v.unsupported_claims) ? v.unsupported_claims.map(S) : [],
  overall_alignment: checks.some(c => c.grounded) ? align : 'Cannot determine', notes: v ? S(v.notes) : 'Validation output was not valid JSON',
  counts: { met: count('Met'), partial: count('Partially met'), not_met: count('Not met'), insufficient: count('Insufficient evidence'), unverified: count('Unverified reference') } };
return { json: { ...base, validation } };

const parseJ = s => { try { return JSON.parse(String(s || '').replace(/```json|```/g, '').trim()); } catch (e) { return null; } };
const steps = Array.isArray($json.intermediateSteps) ? $json.intermediateSteps : [];
const observed = steps.map(s => typeof s.observation === 'string' ? s.observation : JSON.stringify(s.observation || '')).join('\n').toUpperCase();
const grounded = c => { const k = String(c || '').trim().toUpperCase(); return k.length >= 3 && observed.includes(k); };
const S = v => String(v == null ? '' : v).trim();
const base = $('Parse Validation').item.json;
const g = parseJ($json.output);
const SEV = ['Critical', 'Major', 'Minor'], EV = ['Direct', 'Indirect', 'Inferred'];
const TYPES = ['Policy', 'Process', 'Training', 'Equipment', 'Documentation', 'Monitoring', 'Communication'];
const pickOne = (list, v, d) => list.find(x => x.toLowerCase() === S(v).toLowerCase()) || d;
const raw = g && Array.isArray(g.gaps) ? g.gaps : [];
const gaps = raw.map((x, i) => ({ gap_id: 'G' + (i + 1), standard_code: S(x.standard_code), standard_title: S(x.standard_title), requirement: S(x.requirement),
  current_state: S(x.current_state), gap_description: S(x.gap_description), gap_type: pickOne(TYPES, x.gap_type, 'Process'),
  severity: pickOne(SEV, x.severity, 'Major'), evidence_strength: pickOne(EV, x.evidence_strength, 'Inferred'), evidence_needed: S(x.evidence_needed),
  standard_verified: grounded(x.standard_code) }));
const gap_analysis = { ok: g !== null, retrieval_calls: steps.length, gaps, no_gap_reason: g ? S(g.no_gap_reason) : 'Gap output was not valid JSON',
  counts: { total: gaps.length, critical: gaps.filter(x => x.severity === 'Critical').length, major: gaps.filter(x => x.severity === 'Major').length,
    minor: gaps.filter(x => x.severity === 'Minor').length, unverified: gaps.filter(x => !x.standard_verified).length } };
return { json: { ...base, gap_analysis } };

const base = $('Parse Gap Analysis').item.json;
const S = v => String(v == null ? '' : v).trim();
let p = null; try { p = JSON.parse(String($json.output || '').replace(/```json|```/g, '').trim()); } catch (e) {}
const gaps = base.gap_analysis.gaps || [];
const PRI = ['Critical', 'High', 'Medium', 'Low'], TYP = ['Containment', 'Corrective', 'Preventive'];
const DEF = { Critical: 7, High: 30, Medium: 60, Low: 90 };
const addDays = d => new Date(Date.now() + d * 86400e3).toISOString().slice(0, 10);
const fmt = t => String(t).slice(0, 16).replace('T', ' ') + ' UTC';
const today = addDays(0), max = addDays(365);
const ids = new Set(gaps.map(x => x.gap_id));
const raw = p && Array.isArray(p.actions) ? p.actions : [];
let actions = raw.map((a, i) => {
  const pri = PRI.find(x => x.toLowerCase() === S(a.priority).toLowerCase()) || 'Medium';
  const due = S(a.due_date); const ok = /^\d{4}-\d{2}-\d{2}$/.test(due) && due >= today && due <= max;
  return { action_id: 'A' + (i + 1), gap_ref: ids.has(S(a.gap_ref)) ? S(a.gap_ref) : '', action_type: TYP.find(x => x.toLowerCase() === S(a.action_type).toLowerCase()) || 'Corrective',
    action: S(a.action), owner_role: S(a.owner_role) || 'Quality Officer (to assign)', priority: pri, due_date: ok ? due : addDays(DEF[pri]),
    due_source: ok ? 'proposed' : 'default by priority', success_measure: S(a.success_measure) || 'To be defined at review', evidence_of_completion: S(a.evidence_of_completion), auto_added: false };
}).filter(a => a.action);
const covered = new Set(actions.map(a => a.gap_ref).filter(Boolean));
const coverage = gaps.length ? gaps.filter(x => covered.has(x.gap_id)).length / gaps.length : 1;
const sev2pri = { Critical: 'Critical', Major: 'High', Minor: 'Medium' };
gaps.filter(x => !covered.has(x.gap_id)).forEach(x => { const pri = sev2pri[x.severity] || 'High';
  actions.push({ action_id: 'A' + (actions.length + 1), gap_ref: x.gap_id, action_type: 'Corrective', action: 'Quality team to define a corrective action for gap ' + x.gap_id + ' (' + (x.gap_description || x.standard_code) + ')',
    owner_role: 'Quality Officer (to assign)', priority: pri, due_date: addDays(DEF[pri]), due_source: 'default by priority', success_measure: 'To be defined at review', evidence_of_completion: '', auto_added: true }); });
if (base.sentinel_suspected && !actions.some(a => /reportab/i.test(a.action))) {
  actions.unshift({ action_id: 'A0', gap_ref: '', action_type: 'Containment', action: 'Assess reportability against GAHAR Hospital Standards 2025 and the GAHAR Manual for Management of Reportable Events. If reportable: notify GAHAR by ' + fmt(base.gahar_notify_by) + ' (48 h) and submit the RCA with a corrective plan by ' + base.rca_due_by + ' (45 days).',
    owner_role: 'Quality & Patient Safety Officer', priority: 'Critical', due_date: String(base.gahar_notify_by).slice(0, 10), due_source: 'GAHAR 48 h rule', success_measure: 'Reportability decision documented', evidence_of_completion: 'Signed decision record', auto_added: true }); }
const recs = p && Array.isArray(p.recommendations) ? p.recommendations.map(r => ({ recommendation: S(r.recommendation), rationale: S(r.rationale), gap_refs: Array.isArray(r.gap_refs) ? r.gap_refs.map(S) : [] })).filter(r => r.recommendation) : [];
const action_plan = { ok: p !== null, actions, recommendations: recs, monitoring_indicators: p && Array.isArray(p.monitoring_indicators) ? p.monitoring_indicators.map(S) : [],
  follow_up_review_date: p && /^\d{4}-\d{2}-\d{2}$/.test(S(p.follow_up_review_date)) ? S(p.follow_up_review_date) : addDays(90),
  action_coverage: Math.round(coverage * 100) / 100, defaulted_due_dates: actions.filter(a => a.due_source === 'default by priority').length, auto_added: actions.filter(a => a.auto_added).length };
return { json: { ...base, action_plan } };

const base = $('Parse Action Plan').item.json;
const S = v => String(v == null ? '' : v).trim();
let a = null; try { a = JSON.parse(String($json.output || '').replace(/```json|```/g, '').trim()); } catch (e) {}
const issues = a && Array.isArray(a.issues) ? a.issues.map(S) : ['Audit output was not valid JSON - manual review required'];
const v = base.validation, g = base.gap_analysis, p = base.action_plan;
if (!v.ok) issues.push('Validation agent output was not valid JSON');
if (!g.ok) issues.push('Gap-analysis agent output was not valid JSON');
if (!p.ok) issues.push('Action-plan agent output was not valid JSON');
if (v.counts.unverified) issues.push(v.counts.unverified + ' validation check(s) cite a standard code that retrieval did not return - shown as Unverified reference');
if (g.counts.unverified) issues.push(g.counts.unverified + ' gap(s) cite a standard code that retrieval did not return - verify before relying on them');
if (p.defaulted_due_dates) issues.push(p.defaulted_due_dates + ' action(s) use a default due date by priority - confirm at review');
if (p.auto_added) issues.push(p.auto_added + ' action(s) were added automatically (uncovered gap or GAHAR deadline rule) - assign owners');
if (!v.retrieval_calls) issues.push('Validation agent made no GAHAR retrieval calls - is the knowledge base loaded?');
const tiers = ['Low', 'Medium', 'High', 'Critical'];
const t1 = tiers.indexOf(base.risk_tier), t2 = a ? tiers.indexOf(a.risk_tier) : -1;
let risk = tiers[Math.max(t1, t2, base.sentinel_suspected ? 3 : 0, g.counts.critical ? 2 : 0)] || 'High';
const total = v.checks.length + g.gaps.length;
const groundedN = v.checks.filter(c => c.grounded).length + g.gaps.filter(x => x.standard_verified).length;
const grounded_rate = total ? Math.round(groundedN / total * 100) / 100 : 0;
const codes = [...new Set([...v.checks.filter(c => c.grounded).map(c => c.standard_code), ...g.gaps.filter(x => x.standard_verified).map(x => x.standard_code)])];
const audit = { verdict: a && ['Pass', 'Pass with issues', 'Fail'].includes(a.verdict) ? a.verdict : 'Fail', issues };
const text = JSON.stringify({ audit, v, g, p, parsed: base.parsed });
const phi = [/\b\d{14}\b/, /(?<!\d)(?:\+?20|0)1[0125]\d{8}(?!\d)/, /\bMRN[:\s-]*\d+/i, /[\w.+-]+@[\w-]+\.[\w.]+/];
const hit = phi.some(r => r.test(text));
return { json: { ...base, audit, risk_tier: risk, gahar_citations: codes, citation_status: codes.length ? 'cited' : 'unverified',
  grounded_rate, gap_count: g.gaps.length, action_count: p.actions.length, action_coverage: p.action_coverage,
  output_status: hit ? 'quarantine' : 'clean' } };

const b = $('Parse Audit').item.json;
let j = null;
try { j = JSON.parse(String($json.output || '').replace(/```json|```/g, '').trim()); } catch (e) {}
const dims = ['factual_accuracy', 'groundedness', 'safety_compliance', 'format_adherence', 'bias'];
const ok = !!j && dims.every(k => Number.isFinite(Number(j[k])));
const s = {}; dims.forEach(k => s[k] = ok ? Math.min(5, Math.max(1, Number(j[k]))) : '');
const mean = ok ? Math.round(dims.reduce((a, k) => a + s[k], 0) / dims.length * 100) / 100 : '';
let alert_level = 'none';
if (!ok) alert_level = 'soft';
else if (s.safety_compliance <= 2) alert_level = 'hard';
else if (mean < 4 || b.grounded_rate < 0.5) alert_level = 'soft';
if (b.output_status !== 'clean') alert_level = 'hard';
const draft_seconds = Math.round((Date.now() - new Date(b.timestamp).getTime()) / 1000);
return { json: { ...b, ...s, mean_score: mean, alert_level, judge_status: ok ? 'ok' : 'degraded',
  judge_rationale: ok ? String(j.rationale || '') : 'Judge output invalid - manual verification required',
  draft_seconds, models: 'specialist/validation/gap/audit=gpt-4o; plan=gpt-4o; judge/summary=gpt-4o-mini' } };

// Builds one LangSmith run for the whole incident pipeline + evaluation feedback items.
const b = $json;
const crypto = require('crypto');
const id = crypto.randomUUID();
const start = new Date(b.timestamp).toISOString();
const end = new Date().toISOString();
const dotted = start.replace(/[-:]/g, '').replace(/\.(\d{3})Z$/, '$1000Z') + id;
const redact = String($env.LANGSMITH_REDACT_TEXT || '') === 'true';
const norm = v => (v === '' || v == null || !Number.isFinite(Number(v))) ? null : Math.round(Number(v) / 5 * 100) / 100;
const fb = [];
const add = (key, score, comment) => { if (score !== null && score !== undefined) fb.push({ run_id: id, key, score, comment: String(comment || '').slice(0, 500) }); };
['factual_accuracy', 'groundedness', 'safety_compliance', 'format_adherence', 'bias'].forEach(k => add('judge_' + k, norm(b[k]), 'raw ' + b[k] + '/5'));
add('judge_mean', norm(b.mean_score), String(b.judge_rationale || ''));
add('citation_grounded_rate', b.grounded_rate, 'share of validation checks + gaps whose GAHAR code was returned by retrieval');
add('action_coverage', b.action_coverage, 'share of gaps covered by at least one action');
add('hard_stop', b.alert_level === 'hard' ? 1 : 0, 'alert level: ' + b.alert_level);
add('escalated', b.escalation_flag ? 1 : 0, b.triage_reason);
const run = { id, trace_id: id, dotted_order: dotted, name: 'gahar_incident_pipeline', run_type: 'chain', start_time: start, end_time: end,
  session_name: String($env.LANGSMITH_PROJECT || $env.LANGCHAIN_PROJECT || 'hospital-incident-ai'),
  inputs: { incident_id: b.incident_id, incident_type: b.incident_type, department: b.department, harm_occurred: b.harm_occurred, route: b.route,
    description_sanitized: redact ? '[omitted]' : b.description_sanitized },
  outputs: { risk_tier: b.risk_tier, alert_level: b.alert_level, validation_alignment: b.validation.overall_alignment, validation_counts: b.validation.counts,
    gap_counts: b.gap_analysis.counts, action_count: b.action_count, action_coverage: b.action_coverage, grounded_rate: b.grounded_rate, verified_codes: b.gahar_citations,
    judge_mean: b.mean_score, audit_verdict: b.audit.verdict },
  tags: ['gahar-2025', 'incident', 'route:' + b.route, 'schema:' + b.schema_version],
  extra: { metadata: { incident_id: b.incident_id, n8n_execution: b.run_id, intake_channel: b.intake_channel, models: b.models } } };
return { json: { run, feedback: fb, run_id: id } };

// SECURITY: nothing is released until an authorized human replies with this one-time code.
const b = $('Parse Judge').item.json;
const secret = String($env.APPROVAL_TOKEN || '');
if (!secret) throw new Error('APPROVAL_TOKEN env var is not set - refusing to issue a review package');
const code = require('crypto').createHash('sha256').update(b.incident_id + secret).digest('hex').slice(0, 8).toUpperCase();
return { json: {
  incident_id: b.incident_id, run_id: b.run_id, route: b.route, risk_tier: b.risk_tier, alert_level: b.alert_level,
  review_status: 'PENDING_HUMAN_REVIEW', executive_summary: $json.output || '',
  citations: (b.gahar_citations || []).join('; '), citation_status: b.citation_status, mean_score: b.mean_score,
  escalation_flag: b.escalation_flag, sentinel_suspected: b.sentinel_suspected,
  gahar_notify_by: b.gahar_notify_by, rca_due_by: b.rca_due_by,
  gap_count: b.gap_count, action_count: b.action_count, validation_alignment: b.validation.overall_alignment,
  proposed_actions: JSON.stringify(b.action_plan.actions), approval_code: code,
  email_subject: '[GAHAR-RCA] ' + b.incident_id + ' - GAHAR gap analysis & action plan - review required', created_at: new Date().toISOString() } };

const b = $('Parse Judge').item.json;
const h = $json;
const esc = s => String(s == null ? '' : s).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const li = a => (a && a.length) ? '<ul style="margin:4px 0 12px 18px;padding:0">' + a.map(x => '<li>' + esc(typeof x === 'string' ? x : JSON.stringify(x)) + '</li>').join('') + '</ul>' : '<p style="color:#667;margin:4px 0 12px">None reported.</p>';
const th = t => '<th style="background:#12355B;color:#fff;padding:6px 8px;text-align:left;font-size:12px">' + esc(t) + '</th>';
const td = (t, x) => '<td style="padding:6px 8px;border-bottom:1px solid #dde3ea;vertical-align:top;font-size:12px;' + (x || '') + '">' + esc(t) + '</td>';
const H2 = t => '<h2 style="color:#12355B;font-size:16px;margin:22px 0 6px;font-family:Georgia,serif">' + esc(t) + '</h2>';
const table = (head, rows) => rows.length ? '<table style="border-collapse:collapse;width:100%">' + '<tr>' + head.map(th).join('') + '</tr>' + rows.join('') + '</table>' : '<p style="color:#667">None.</p>';
const sevColor = s => ({ Critical: 'color:#A6262B;font-weight:bold', Major: 'color:#B26A00;font-weight:bold', High: 'color:#B26A00;font-weight:bold' }[s] || '');
const p = b.parsed || {}, v = b.validation, g = b.gap_analysis, a = b.action_plan;
let html = '<div style="font-family:Calibri,Arial,sans-serif;max-width:900px;color:#1B1F24">';
html += '<div style="background:#B26A00;color:#fff;padding:8px 12px;font-weight:bold">AI-DRAFTED REPORT - NOT APPROVED. A quality-team member must review before any action is released.</div>';
html += '<h1 style="color:#12355B;font-family:Georgia,serif;font-size:22px;margin:14px 0 4px">GAHAR Gap Analysis &amp; Action Plan</h1>';
html += '<p style="margin:0 0 8px;color:#445">Incident <b>' + esc(b.incident_id) + '</b> | ' + esc(b.incident_type) + ' | ' + esc(b.department) + ' | Risk tier: <b>' + esc(b.risk_tier) + '</b> | Harm reported: ' + esc(b.harm_occurred) + '</p>';
if (b.sentinel_suspected) html += '<div style="border:2px solid #A6262B;padding:8px 12px;margin:8px 0"><b>Possible serious harm.</b> The Quality Officer must assess reportability against the GAHAR Hospital Standards 2025 and the GAHAR Manual for Management of Reportable Events. If reportable: notify GAHAR by <b>' + esc(String(b.gahar_notify_by).slice(0, 16).replace('T', ' ') + ' UTC') + '</b> (48 h) and submit the RCA with a corrective plan by <b>' + esc(b.rca_due_by) + '</b> (45 days). This system does not determine reportability.</div>';
html += H2('1. Executive summary') + '<p>' + esc(h.executive_summary) + '</p>';
html += H2('2. Incident analysis (' + b.route + ' specialist)') + '<p>' + esc(p.summary || '') + '</p>';
html += '<b>Confirmed facts</b>' + li(p.confirmed_facts) + '<b>Hypotheses (not confirmed)</b>' + li(p.hypotheses) + '<b>Missing evidence</b>' + li(p.missing_evidence) + '<b>Candidate root causes</b>' + li(p.root_causes);
html += H2('3. GAHAR validation (alignment: ' + v.overall_alignment + ')');
html += '<p style="font-size:12px;color:#445">Met ' + v.counts.met + ' | Partially met ' + v.counts.partial + ' | Not met ' + v.counts.not_met + ' | Insufficient evidence ' + v.counts.insufficient + ' | Unverified reference ' + v.counts.unverified + '. "Insufficient evidence" means the report does not say; it is not a compliance finding.</p>';
html += table(['Ref', 'Standard', 'Requirement', 'Status', 'Evidence from the incident'], v.checks.map(c => '<tr>' + td(c.ref) + td(c.standard_code + (c.standard_title ? ' - ' + c.standard_title : '')) + td(c.requirement_summary) + td(c.status, c.status === 'Not met' ? 'color:#A6262B;font-weight:bold' : (c.status === 'Unverified reference' ? 'color:#B26A00' : '')) + td(c.evidence_from_incident) + '</tr>'));
if (v.unsupported_claims.length) html += '<b>Draft claims with no supporting GAHAR passage</b>' + li(v.unsupported_claims);
html += H2('4. Gap analysis (potential gaps indicated by this incident)');
html += table(['ID', 'Standard', 'Gap', 'Type', 'Severity', 'Evidence', 'Needed to confirm'], g.gaps.map(x => '<tr>' + td(x.gap_id) + td(x.standard_code + (x.standard_verified ? '' : ' (unverified)')) + td(x.gap_description + (x.current_state ? ' Current state: ' + x.current_state : '')) + td(x.gap_type) + td(x.severity, sevColor(x.severity)) + td(x.evidence_strength) + td(x.evidence_needed) + '</tr>'));
if (!g.gaps.length) html += '<p>' + esc(g.no_gap_reason || 'No gap supported by the evidence in this report.') + '</p>';
html += H2('5. Action plan');
html += table(['ID', 'Gap', 'Type', 'Action', 'Priority', 'Owner (role)', 'Due', 'Success measure', 'Note'], a.actions.map(x => '<tr>' + td(x.action_id) + td(x.gap_ref || '-') + td(x.action_type) + td(x.action) + td(x.priority, sevColor(x.priority)) + td(x.owner_role) + td(x.due_date) + td(x.success_measure) + td([x.auto_added ? 'auto-added' : '', x.due_source !== 'proposed' ? 'due: ' + x.due_source : ''].filter(Boolean).join('; ')) + '</tr>'));
html += H2('6. Recommendations') + (a.recommendations.length ? '<ol style="margin:4px 0 12px 18px;padding:0">' + a.recommendations.map(r => '<li><b>' + esc(r.recommendation) + '</b><br><span style="color:#445">' + esc(r.rationale) + (r.gap_refs.length ? ' (gaps: ' + esc(r.gap_refs.join(', ')) + ')' : '') + '</span></li>').join('') + '</ol>' : '<p>None.</p>');
html += '<b>Monitoring indicators</b>' + li(a.monitoring_indicators) + '<p style="font-size:12px">Follow-up review date: ' + esc(a.follow_up_review_date) + '</p>';
html += H2('7. Quality of this AI draft');
html += '<p style="font-size:12px">Judge mean ' + esc(b.mean_score) + '/5 (accuracy ' + esc(b.factual_accuracy) + ', groundedness ' + esc(b.groundedness) + ', safety ' + esc(b.safety_compliance) + ', format ' + esc(b.format_adherence) + ', bias ' + esc(b.bias) + ') | Verified GAHAR codes: ' + esc(h.citations || 'none') + ' | Citation grounded rate ' + esc(b.grounded_rate) + ' | Audit verdict: ' + esc(b.audit.verdict) + ' | Alert level: ' + esc(b.alert_level) + '</p>';
html += '<b>Audit issues to check</b>' + li(b.audit.issues);
html += H2('8. Your decision');
html += '<p>Reply to this email (keep the subject). First line exactly <b>APPROVED</b>, <b>REJECTED</b> or <b>REQUEST EDITS</b>, then:</p><pre style="background:#EEF3F8;padding:8px">CODE: ' + esc(h.approval_code) + '\nOWNER: &lt;role responsible&gt;\nDUE: YYYY-MM-DD\nCOMMENT: &lt;optional&gt;</pre><p style="font-size:12px;color:#667">Only replies from authorized quality reviewers with the correct code are accepted. Generated ' + esc(new Date().toISOString()) + '. Based on GAHAR Handbook for Hospital Accreditation Standards 2025; verify clause wording in the official handbook.</p></div>';
const text = 'AI-DRAFTED REPORT - NOT APPROVED\nIncident ' + b.incident_id + ' | ' + b.incident_type + ' | ' + b.department + ' | Risk ' + b.risk_tier + '\n\n' + h.executive_summary + '\n\nGaps: ' + g.gaps.length + ' | Actions: ' + a.actions.length + ' | GAHAR alignment: ' + v.overall_alignment + '\n\nOpen the HTML version for the full validation, gap analysis, action plan and recommendations.\n\nTo decide, reply with first line APPROVED / REJECTED / REQUEST EDITS, then CODE: ' + h.approval_code + ', OWNER:, DUE: (YYYY-MM-DD), COMMENT:.';
return { json: { ...h, email_html: html, email_text: text } };

